nextflow_process {

    name "Test Process BLOBTK_SNAIL"
    script "../main.nf"
    process "BLOBTK_SNAIL"

    tag "modules"
    tag "modules_nfcore"
    tag "blobtk"
    tag "blobtk/snail"
    tag "blobtk/create"


    test("bacteroides fragilis - fasta - svg") {

        when {

            process {
                """
                input[0] = Channel.of(
                    [
                        [ id:'test' ], // meta map
                        file(params.modules_testdata_base_path + "genomics/prokaryotes/bacteroides_fragilis/genome/genome.fna.gz", checkIfExists: true),
                        []
                    ]
                )
                input[1] = Channel.of([[:],[]])
                input[2] = Channel.of("svg")
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }

